def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > 0:
                    dangerous_prev.append(float(bid))

    if not alive:
        base = 12.0 if hp > 3 else 28.0
        return float(min(budget, base))

    high_prev = max(dangerous_prev) if dangerous_prev else 0.0
    avg_prev = sum(dangerous_prev) / len(dangerous_prev) if dangerous_prev else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.6
    elif hp <= 6:
        urgency += 0.25

    if no_water >= 2:
        urgency += 1.0
    elif no_water >= 1:
        urgency += 0.45

    if day >= 8:
        urgency += 0.2

    cindy_alive = False
    eric_alive = False
    for oid, opp in alive:
        if oid == 'Cindy':
            cindy_alive = True
        if oid == 'Eric':
            eric_alive = True

    if hp <= 2 or no_water >= 2:
        emergency = max(92.0, high_prev + 3.0)
        if cindy_alive:
            emergency = max(emergency, 106.0)
        return float(min(budget, emergency))

    if supply >= 23 and hp >= 7 and no_water == 0:
        return float(min(budget, 8.0))

    if supply <= 17:
        target = 48.0 + 26.0 * scarcity + 18.0 * urgency
        if high_prev > 0:
            target = max(target, min(high_prev + 2.0, 104.0))
        if cindy_alive and urgency >= 0.8:
            target = max(target, 106.0)
        return float(min(budget, target))

    target = 20.0 + 18.0 * scarcity + 16.0 * urgency
    if eric_alive and avg_prev > 0:
        target = max(target, min(avg_prev + 1.5, 82.0))
    if cindy_alive and urgency < 0.8:
        target = min(target, 72.0)

    if hp >= 8 and no_water == 0 and supply >= 20:
        target = min(target, 24.0)

    target = max(0.0, target)
    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents, bid conservatively
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Pressure estimate: who was willing to pay a lot yesterday?
    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev

    # Determine aggressiveness based on supply scarcity and my hp
    # When supply is low, winning the allocation matters more.
    scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY + 1e-9)
    scarcity = max(0.0, min(1.0, scarcity))

    # If I'm at risk, bid more aggressively.
    if hp <= 2.0 or no_water_days >= 2:
        base = DAILY_SALARY * (0.75 + 0.25 * scarcity)
    elif hp <= 4.0:
        base = DAILY_SALARY * (0.55 + 0.25 * scarcity)
    else:
        base = DAILY_SALARY * (0.45 + 0.25 * scarcity)

    # Use yesterday's highest bid as a ceiling/anchor.
    # Aim to slightly undercut the top payer unless my hp is critical.
    # If highest_prev is very high, don't chase fully; bid enough to beat typical mid bids.
    if highest_prev >= DAILY_SALARY * 0.95:
        # Cindy-like behavior: high bids. Try to beat her only if necessary.
        if hp <= 4.0 or no_water_days >= 2:
            target = min(budget, highest_prev - 1.0)
            bid = max(base, target)
        else:
            bid = min(budget, max(base, second_prev + 1.0))
    else:
        # Typical: match/beat second-highest slightly.
        bid = max(base, second_prev + 1.5)
        # If someone bid very high relative to my base, cap to avoid overpaying.
        if highest_prev > 0.0:
            bid = min(bid, highest_prev + 0.5)

    # Final budget and non-negative constraints
    bid = max(0.0, min(budget, bid))

    # If supply is extremely low (near 15), ensure we don't underbid too much.
    if supply <= (MIN_SUPPLY + 1.0):
        bid = max(bid, DAILY_SALARY * 0.6)
        bid = min(bid, budget)

    return float(bid)

